public static int countBigChanges(double[] temps) {
    int count = 0;
    for (int i = 1; i < temps.length; i++) {
        if (Math.abs(temps[i] - temps[i - 1]) > 0.5) {
            count++;
        }
    }
    return count;
}

public static double maxChange(double[] temps) {
    double max = 0;
    for (int i = 1; i < temps.length; i++) {
        double d = Math.abs(temps[i] - temps[i - 1]);
        if (d > max) {
            max = d;
        }
    }
    return max;
}

