public static String check(Object got, Object expected) {
    String g = String.valueOf(got).trim();
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

exercise.mainCode:
System.out.println("סעיף א, בדיקה 1 (הדוגמה): " + check(countBigChanges(new double[] { 37.0, 37.5, 38.25, 38.0, 37.25, 37.25, 38.75 }), 3));
System.out.println("סעיף א, בדיקה 2 (מרחק 0.5 בדיוק לא נספר): " + check(countBigChanges(new double[] { 37.0, 37.5, 37.0 }), 0));
System.out.println("סעיף א, בדיקה 3 (החום יורד — גם נספר): " + check(countBigChanges(new double[] { 39.0, 38.25, 37.5 }), 2));
System.out.println("סעיף א, בדיקה 4 (שתי מדידות): " + check(countBigChanges(new double[] { 36.5, 37.25 }), 1));
System.out.println("סעיף ב, בדיקה 1 (הדוגמה): " + check(maxChange(new double[] { 37.0, 37.5, 38.25, 38.0, 37.25, 37.25, 38.75 }), 1.5));
System.out.println("סעיף ב, בדיקה 2 (המרחק הגדול — ירידה): " + check(maxChange(new double[] { 37.0, 37.5, 39.75, 37.25 }), 2.5));
System.out.println("סעיף ב, בדיקה 3 (המרחק הגדול — בהתחלה): " + check(maxChange(new double[] { 36.5, 38.0, 38.25 }), 1.5));
System.out.println("סעיף ב, בדיקה 4 (שתי מדידות שוות): " + check(maxChange(new double[] { 37.25, 37.25 }), 0.0));

